function wordCount(sentence) {
  const counts = {};
  if (sentence === '') {
    return counts;
  }
  for (const word of sentence.toLowerCase().split(' ')) {
    if (Object.prototype.hasOwnProperty.call(counts, word)) {
      counts[word] += 1;
    } else {
      counts[word] = 1;
    }
  }
  return counts;
}

`hasOwnProperty` only looks at the object's own keys, so words such as `constructor` start at 1 instead of picking up an inherited value.
